#include <iostream>
#include <vector>

int main() {
    std::vector<int> scores{5, 8};
    scores.push_back(9);
    std::cout << scores.at(0) << "\n";
    std::cout << scores.size() << "\n";
}

#include <iostream>
#include <map>
#include <string>

int main() {
    std::map<std::string, int> pencils{{"Asha", 3}, {"Ravi", 5}};
    std::cout << pencils.at("Ravi") << "\n";
}

#include <iostream>
#include <set>

int main() {
    std::set<int> badges{2, 1, 2};
    for (int badge : badges) {
        std::cout << badge << "\n";
    }
}
